// Local control preferences, an original pet studio, equipment and level-50 mastery.
const MAX_PLAYER_LEVEL=100;
const LOOK_PALETTE=['#dfb87b','#303744','#f0dfc6','#8b97a6','#b97743','#ffffff','#a98ce0','#f3a6bf','#7acfc4','#79b3e8'];
const OUTFIT_PALETTE=['#535b78','#447f77','#8d588e','#ac624b','#436990','#bd993f'];
const EYE_PALETTE=['natural','#735033','#7bb8dc','#8eb48c','#d49b56','#a98ce0'];
const LOOK_DEFAULT={coat:'natural',hair:'breed',hairColour:'#303744',eyes:'natural',outfit:'#535b78',accessory:'none'};
function sanitiseLook(value){const v=value&&typeof value==='object'?value:{};return{coat:['natural',...LOOK_PALETTE].includes(v.coat)?v.coat:'natural',hair:['breed','swoop','spiky','curly'].includes(v.hair)?v.hair:'breed',hairColour:LOOK_PALETTE.includes(v.hairColour)?v.hairColour:'#303744',eyes:EYE_PALETTE.includes(v.eyes)?v.eyes:'natural',outfit:OUTFIT_PALETTE.includes(v.outfit)?v.outfit:'#535b78',accessory:['none','glasses','headphones','cap'].includes(v.accessory)?v.accessory:'none'}}
function lookFor(id=profile.hero){return sanitiseLook(profile.avatarLooks?.[id])}
playerLevel=function(){return Math.min(MAX_PLAYER_LEVEL,Math.floor(Math.max(0,Number(profile.xp)||0)/150)+1)};
function masteryBonuses(level=playerLevel()){const n=Math.max(0,Math.min(100,Number(level)||1)-26);return{hp:Math.floor(n/4),damage:Math.floor(n/8),superDamage:Math.floor(n/8)*2,speed:n*.3}}
function getBattleHero(id=profile.hero,level=playerLevel()){const h=HEROES.find(h=>h.id===id)||HEROES[0],b=masteryBonuses(level);return{...h,hp:h.hp+b.hp,damage:h.damage+b.damage,superDamage:h.superDamage+b.superDamage,speed:h.speed+b.speed,playerLevel:Math.min(100,Math.max(1,Number(level)||1))}}
ensureAvatar=function(){if(!canSelectAvatar(HEROES.find(h=>h.id===profile.hero)))profile.hero='dog-1';return getBattleHero(profile.hero)};
const WEAPONS=[
{id:'spark',name:'Spark Blaster',level:1,icon:'ϟ',colour:'#d5fa59',shots:1,spread:0,damage:1,delay:1,range:460,pierce:0,desc:'A dependable, energy-efficient single shot.'},
{id:'burst',name:'Comet Burst',level:5,icon:'⋮',colour:'#9fe6ff',shots:3,spread:.07,damage:.55,delay:1.6,range:460,pierce:0,desc:'Three tightly grouped shots. A longer pause between bursts.'},
{id:'scatter',name:'Rainbow Scatter',level:10,icon:'✺',colour:'#f5abde',shots:5,spread:.19,damage:.45,delay:1.9,range:330,pierce:0,desc:'A wide, short-range spread for close groups of bots.'},
{id:'rapid',name:'Neon Repeater',level:20,icon:'»',colour:'#a9f0d4',shots:1,spread:0,damage:.6,delay:.55,range:430,pierce:0,desc:'Fast, lighter shots. Watch your energy supply.'},
{id:'pierce',name:'Prism Lance',level:35,icon:'➶',colour:'#c6b4ff',shots:1,spread:0,damage:1.4,delay:1.7,range:560,pierce:2,desc:'A slower beam that can pass through three aligned bots.'},
{id:'nova',name:'Cosmic Nova',level:50,icon:'✦',colour:'#ffd889',shots:3,spread:.12,damage:1.1,delay:2.1,range:510,pierce:1,desc:'A powerful fan of piercing stars. The level-50 reward.'}
];
function weaponFor(id=profile.weapon,level=playerLevel()){const w=WEAPONS.find(w=>w.id===id);return w&&level>=w.level?w:WEAPONS[0]}
function weaponShots(g,p,w,angle){for(let i=0;i<w.shots;i++){const a=angle+(i-(w.shots-1)/2)*w.spread;g.bullets.push({x:p.x,y:p.y,dx:Math.cos(a)*700,dy:Math.sin(a)*700,life:w.range/700,damage:Math.round(p.damage*w.damage*100)/100,pierce:w.pierce,colour:w.colour,owner:p.id})}}
function advancePiercingShot(b,e){if(!(b.pierce>0))return false;b.pierce--;const speed=Math.hypot(b.dx,b.dy)||1;b.x+=b.dx/speed*(e.r*2+15);b.y+=b.dy/speed*(e.r*2+15);return true}
const customShootBase=shoot;
shoot=function(){if(live?.battleStarted){const g=game,w=weaponFor();if(!g||g.paused||g.cooldown>0||g.hp<=0||g.ammo<=0)return;live.state.shot++;g.cooldown=g.hero.shotDelay*w.delay;if(!live.host){g.ammo--;GameAudio.effect('shoot')}return}const g=game;if(!g||g.paused||g.cooldown>0||g.ammo<=0)return;const w=weaponFor(g.weapon),e=g.enemies.filter(e=>e.hp>0&&e.spawnShield<=0&&Math.hypot(e.x-g.x,e.y-g.y)<w.range&&lineClear(g,g.x,g.y,e.x,e.y,6)).sort((a,b)=>Math.hypot(a.x-g.x,a.y-g.y)-Math.hypot(b.x-g.x,b.y-g.y))[0];if(!e)return;weaponShots(g,{x:g.x,y:g.y,damage:g.attackPower},w,Math.atan2(e.y-g.y,e.x-g.x));g.ammo--;g.cooldown=g.hero.shotDelay*w.delay;g.zaps=.12;GameAudio.effect('shoot')};
fireLiveUnit=function(p){const g=game,h=getBattleHero(p.hero,p.level),w=weaponFor(p.weapon,p.level);if(p.hp<=0||p.ammo<=0||p.cooldown>0)return;const e=g.enemies.filter(e=>e.hp>0&&e.spawnShield<=0&&Math.hypot(e.x-p.x,e.y-p.y)<w.range&&lineClear(g,p.x,p.y,e.x,e.y,6)).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(!e)return;weaponShots(g,{...p,damage:h.damage},w,Math.atan2(e.y-p.y,e.x-p.x));p.ammo--;p.cooldown=h.shotDelay*w.delay;if(p.id===live.selfId)GameAudio.effect('shoot')};
let renderingLook=null,renderingWeapon=null,studioDraft=null,studioId=null,layoutDraft=null,layoutDrag=null,controlsReturnPaused=null;
const naturalEyes=artEyes;artEyes=function(left,right=left,wide=false){const eye=renderingLook?.eyes;if(eye&&eye!=='natural')left=right=eye;return naturalEyes(left,right,wide)};
function hairArtwork(look){const c=look.hairColour,ink='#343442';if(look.hair==='swoop')return `<path d="M77 58Q73 25 104 28Q139 15 153 42L133 39 116 59 104 47 93 62Z" fill="${c}" stroke="${ink}" stroke-width="3"/>`;if(look.hair==='spiky')return `<path d="M77 59L81 28 95 39 109 15 119 38 139 22 146 57 127 51 111 63 94 53Z" fill="${c}" stroke="${ink}" stroke-width="3"/>`;if(look.hair==='curly')return [[83,49],[96,37],[111,33],[126,37],[140,49]].map(([x,y])=>artCircle(x,y,13,c,ink,3)).join('');return ''}
function accessoryArtwork(look){if(look.accessory==='glasses')return '<g fill="#a8e9f022" stroke="#33344d" stroke-width="4"><rect x="66" y="79" width="36" height="30" rx="10"/><rect x="121" y="79" width="36" height="30" rx="10"/><path d="M102 90Q111 84 121 90" fill="none"/></g>';if(look.accessory==='headphones')return '<path d="M54 98V76Q54 30 111 30Q168 30 168 76V98" fill="none" stroke="#70c9c9" stroke-width="9"/><rect x="47" y="82" width="17" height="36" rx="7" fill="#50708b" stroke="#343442" stroke-width="3"/><rect x="158" y="82" width="17" height="36" rx="7" fill="#50708b" stroke="#343442" stroke-width="3"/>';if(look.accessory==='cap')return '<path d="M73 52Q77 18 111 22Q147 19 153 53Z" fill="#6e83c9" stroke="#343442" stroke-width="3"/><path d="M99 49L172 54Q163 67 115 61Z" fill="#8fa8eb" stroke="#343442" stroke-width="3"/>';return ''}
const breedFaceBase=petFace;
petFace=function(h){const look=renderingLook||sanitiseLook(h.look||lookFor(h.id)),prior=renderingLook;renderingLook=look;try{return breedFaceBase({...h,colour:look.coat==='natural'?h.colour:look.coat})+hairArtwork(look)+accessoryArtwork(look)}finally{renderingLook=prior}};
const naturalHeroSVG=heroSVG;
heroSVG=function(id=profile.hero,extra='',forcedLook,forcedWeapon){const h=HEROES.find(h=>h.id===id)||HEROES[0],prior=renderingLook,oldColour=h.colour,look=sanitiseLook(forcedLook||lookFor(h.id)),w=weaponFor(forcedWeapon||profile.weapon,50);renderingLook=look;if(look.coat!=='natural')h.colour=look.coat;try{let svg=naturalHeroSVG(h.id,extra).replace('fill="#535b78"','fill="'+look.outfit+'"');svg=svg.replace('</svg>',`<g data-weapon="${w.id}" transform="translate(177 157)"><rect x="-1" y="0" width="26" height="16" rx="5" fill="${w.colour}" stroke="#343442" stroke-width="3"/>${Array.from({length:Math.min(3,w.shots)},(_,i)=>`<rect x="19" y="${1+i*5}" width="13" height="4" rx="2" fill="${w.colour}" stroke="#343442" stroke-width="1"/>`).join('')}</g></svg>`);return svg.replace('<svg ','<svg xmlns="http://www.w3.org/2000/svg" ')}finally{h.colour=oldColour;renderingLook=prior}};
getAvatarSprite=function(h){if(typeof window.Image!=='function')return null;const look=sanitiseLook(h.look||lookFor(h.id)),weapon=h.weapon||profile.weapon,equipment={armour:h.armour??(typeof equippedItems==='function'?equippedItems().armour:'none'),shield:h.shieldItem??(typeof equippedItems==='function'?equippedItems().shield:'none'),level:h.playerLevel||playerLevel()},key=h.id+JSON.stringify(look)+weapon+JSON.stringify(equipment);if(!avatarSprites.has(key)){const img=new window.Image();img.decoding='async';img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(heroSVG(h.id,'',look,weapon,equipment));avatarSprites.set(key,img)}return avatarSprites.get(key)};
function studio(){if(live){toast('Leave your live room before changing your look.');return}studioId=profile.hero;studioDraft=lookFor(studioId);openModal(`${topModal('AVATAR STUDIO')}<h2 id="modal-title">Make your companion yours.</h2><p class="sub">Customise your ${ensureAvatar().breed}. Looks are saved for this breed and visible to friends in live rooms.</p><div class="studio-grid"><div id="studio-preview">${heroSVG(studioId,'',studioDraft)}</div><div class="studio-fields">${lookSelect('coat','Fur / skin colour',['natural',...LOOK_PALETTE])}${lookSelect('hair','Hair / tuft style',['breed','swoop','spiky','curly'])}${lookSelect('hairColour','Hair colour',LOOK_PALETTE)}${lookSelect('eyes','Eye colour',EYE_PALETTE)}${lookSelect('outfit','Outfit colour',OUTFIT_PALETTE)}${lookSelect('accessory','Accessory',['none','glasses','headphones','cap'])}</div></div><p class="notice">Breed markings and shapes keep each dog or cat recognisable. Custom looks do not change power.</p><div class="modal-actions"><button class="primary" data-custom="save-look">Save my look →</button><button class="secondary" data-custom="reset-look">Natural breed look</button><button class="text-btn" data-custom="hub">Back</button></div>`)}
const COLOUR_NAMES={'#dfb87b':'Golden','#303744':'Midnight','#f0dfc6':'Cream','#8b97a6':'Silver','#b97743':'Chestnut','#ffffff':'Snow','#a98ce0':'Lilac','#f3a6bf':'Rose','#7acfc4':'Mint','#79b3e8':'Sky','#535b78':'Classic navy','#447f77':'Forest','#8d588e':'Plum','#ac624b':'Rust','#436990':'Ocean','#bd993f':'Gold','#735033':'Brown','#7bb8dc':'Blue','#8eb48c':'Green','#d49b56':'Amber'};
function lookSelect(key,label,values){return `<label>${label}<select data-look="${key}">${values.map(v=>`<option value="${v}" ${studioDraft[key]===v?'selected':''}>${COLOUR_NAMES[v]||({natural:'Natural breed colour',breed:'Natural breed tuft',swoop:'Side sweep',spiky:'Spiky tuft',curly:'Curly tuft',none:'No extra accessory',glasses:'Round glasses',headphones:'Headphones',cap:'Adventure cap'})[v]||v}</option>`).join('')}</select></label>`}
function armoury(){if(live){toast('Leave your live room before changing equipment.');return}const selected=weaponFor();openModal(`${topModal('THE ARMOURY')}<h2 id="modal-title">Find your favourite play style.</h2><p class="sub">Level ${playerLevel()} / 50 · Every weapon uses one energy per trigger. Unlock new styles by learning.</p><div class="weapon-grid">${WEAPONS.map(w=>`<button data-weapon="${w.id}" class="weapon-card ${selected.id===w.id?'selected':''}" aria-pressed="${selected.id===w.id}" ${playerLevel()<w.level?'disabled':''} style="--weapon-colour:${w.colour}"><strong>${w.icon}</strong><h3>${w.name}</h3><p>${w.desc}</p><small>${playerLevel()<w.level?'🔒 Level '+w.level:selected.id===w.id?'EQUIPPED ✓':'Level '+w.level+' · Equip'}</small><span>${w.shots} projectile${w.shots===1?'':'s'} · ${w.range} range · ${w.pierce?'Piercing':'Standard'}</span></button>`).join('')}</div><button class="secondary" data-custom="hub">Back to my setup</button>`)}
function defaultControls(hand='right'){return{hand,move:{x:hand==='left'?.88:.12,y:.80},attack:{x:hand==='left'?.12:.88,y:.80}}}
function cleanControls(raw){const hand=raw?.hand==='left'?'left':'right',defaults=defaultControls(hand),point=(p,d)=>({x:Number.isFinite(p?.x)?Math.min(1,Math.max(0,p.x)):d.x,y:Number.isFinite(p?.y)?Math.min(1,Math.max(0,p.y)):d.y});return{hand,move:point(raw?.move,defaults.move),attack:point(raw?.attack,defaults.attack)}}
function boundedControl(point,width,height,itemWidth,itemHeight){const rx=Math.min(.5,(itemWidth/2+5)/Math.max(1,width)),ry=Math.min(.5,(itemHeight/2+5)/Math.max(1,height));return{x:Math.max(rx,Math.min(1-rx,point.x)),y:Math.max(ry,Math.min(1-ry,point.y))}}
function applyLayout(root,layout=cleanControls(profile.controls)){if(!root)return;const box=root.getBoundingClientRect();if(!box.width||!box.height)return;root.classList.add('layout-custom');for(const[key,selector]of [['move','.movement-hud'],['attack','.battle-actions']]){const item=root.querySelector(selector);if(!item)continue;const bounds=item.getBoundingClientRect(),p=boundedControl(layout[key],box.width,box.height,bounds.width,bounds.height);item.style.left=p.x*100+'%';item.style.top=p.y*100+'%';item.style.right='auto';item.style.bottom='auto';item.style.transform='translate(-50%,-50%)'}root.dataset.hand=layout.hand}
function applyBattleControls(){applyLayout(document.querySelector('.arena-controls'))}
function controlEditor(){if(game&&!game.paused&&!live){controlsReturnPaused=false;game.paused=true;resetControls()}else controlsReturnPaused=game?.paused??null;layoutDraft=cleanControls(profile.controls);openModal(`${topModal('YOUR CONTROLS')}<h2 id="modal-title">Put the controls where you want.</h2><p class="sub">Drag the joystick or attack pad anywhere inside this battlefield preview, then save. Use arrow keys on a selected pad for precise placement.</p><div class="hand-options"><button data-hand="right" aria-pressed="${layoutDraft.hand==='right'}">Right-handed · move left</button><button data-hand="left" aria-pressed="${layoutDraft.hand==='left'}">Left-handed · move right</button></div><div id="control-editor" class="control-editor arena-controls"><div class="editor-map"><i></i><i></i><i></i><i></i><b>YOUR BATTLEFIELD</b></div><div class="movement-hud" data-drag-control="move" tabindex="0" role="button" aria-label="Move joystick. Drag or use arrow keys."><div class="joystick"><span class="joystick-knob">✥</span></div><span class="hud-caption">DRAG JOYSTICK</span></div><div class="battle-actions" data-drag-control="attack" tabindex="0" role="button" aria-label="Move attack buttons. Drag or use arrow keys."><div class="editor-attack"><b>◎</b><strong>ZAP</strong></div><span class="hud-caption">DRAG ATTACK PAD</span></div></div><p class="notice">Position is saved on this device and adapts to screen size. Controls stay within reach when the screen is resized.${live?' Your live battle continues while you edit.':''}</p><div class="modal-actions"><button class="primary" data-custom="save-controls">Set & save positions →</button><button class="secondary" data-custom="reset-controls">Reset positions</button><button class="text-btn" data-custom="hub">Back</button></div>`);applyLayout(document.querySelector('#control-editor'),layoutDraft)}
function personalHub(){openModal(`${topModal('MY SETUP')}<h2 id="modal-title">Your hero. Your way to play.</h2><div class="setup-preview">${heroSVG()}<div><span class="eyebrow">LEVEL ${playerLevel()} / 100</span><h3>${ensureAvatar().breed}</h3><p>${weaponFor().name} · ${cleanControls(profile.controls).hand==='left'?'Left-handed':'Right-handed'} controls</p></div></div><div class="setup-actions"><button class="primary" data-custom="studio">✦ Customise avatar</button><button class="secondary" data-custom="weapons">ϟ Open Armoury</button><button class="secondary" data-custom="controls">✥ Controls & joystick position</button></div><p class="notice">Mastery levels 27–100 add extra life and power to any companion. Monsters grow stronger too. Level 50 unlocks the Cosmic Nova.</p><button class="text-btn" data-custom="done">Back to game</button>`)}
function drawStudioPreview(){const preview=document.querySelector('#studio-preview');if(preview)preview.innerHTML=heroSVG(studioId,'',studioDraft)}
document.addEventListener('change',e=>{if(e.target.dataset.look&&studioDraft){studioDraft=sanitiseLook({...studioDraft,[e.target.dataset.look]:e.target.value});drawStudioPreview()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.hand&&layoutDraft){layoutDraft=defaultControls(b.dataset.hand);document.querySelectorAll('[data-hand]').forEach(n=>n.setAttribute('aria-pressed',String(n.dataset.hand===layoutDraft.hand)));applyLayout(document.querySelector('#control-editor'),layoutDraft);return}if(b.dataset.weapon){const w=WEAPONS.find(w=>w.id===b.dataset.weapon);if(w&&playerLevel()>=w.level){profile.weapon=w.id;if(game)game.weapon=w.id;save();avatarSprites.clear();armoury();toast(w.name+' equipped.')}return}if(!b.dataset.custom)return;e.stopImmediatePropagation();switch(b.dataset.custom){case'hub':personalHub();break;case'studio':studio();break;case'weapons':armoury();break;case'controls':controlEditor();break;case'save-look':profile.avatarLooks??={};profile.avatarLooks[studioId]=sanitiseLook(studioDraft);avatarSprites.clear();save();toast('Your custom look is saved.');studio();break;case'reset-look':studioDraft={...LOOK_DEFAULT};document.querySelectorAll('[data-look]').forEach(n=>n.value=studioDraft[n.dataset.look]);drawStudioPreview();break;case'save-controls':profile.controls=cleanControls(layoutDraft);save();applyBattleControls();toast('Control layout saved.');if(game){closeModal();if(controlsReturnPaused===false)game.paused=false}else personalHub();break;case'reset-controls':layoutDraft=defaultControls(layoutDraft?.hand);applyLayout(document.querySelector('#control-editor'),layoutDraft);break;case'done':closeModal();if(game&&controlsReturnPaused===false)game.paused=false;else if(!game)navigate(currentPage);break}},true);
document.addEventListener('pointerdown',e=>{const item=e.target.closest('[data-drag-control]');if(!item||!layoutDraft)return;e.preventDefault();e.stopImmediatePropagation();layoutDrag={pointer:e.pointerId,key:item.dataset.dragControl};item.setPointerCapture(e.pointerId);moveLayoutPointer(e)},true);
function moveLayoutPointer(e){if(!layoutDrag||layoutDrag.pointer!==e.pointerId)return;const area=document.querySelector('#control-editor'),box=area.getBoundingClientRect(),key=layoutDrag.key;layoutDraft[key]={x:(e.clientX-box.left)/box.width,y:(e.clientY-box.top)/box.height};layoutDraft=cleanControls(layoutDraft);applyLayout(area,layoutDraft)}
document.addEventListener('pointermove',e=>{if(layoutDrag){e.preventDefault();e.stopImmediatePropagation();moveLayoutPointer(e)}},{capture:true,passive:false});
for(const type of ['pointerup','pointercancel','lostpointercapture'])document.addEventListener(type,e=>{if(layoutDrag?.pointer===e.pointerId){layoutDrag=null;e.stopImmediatePropagation()}},true);
document.addEventListener('keydown',e=>{const key=e.target.closest?.('[data-drag-control]')?.dataset.dragControl;if(!key||!layoutDraft)return;const directions={ArrowLeft:[-.02,0],ArrowRight:[.02,0],ArrowUp:[0,-.02],ArrowDown:[0,.02]};if(directions[e.key]){e.preventDefault();const[dx,dy]=directions[e.key];layoutDraft[key].x+=dx;layoutDraft[key].y+=dy;layoutDraft=cleanControls(layoutDraft);applyLayout(document.querySelector('#control-editor'),layoutDraft)}});
window.addEventListener('resize',()=>{resetControls();applyBattleControls();if(layoutDraft&&document.querySelector('#control-editor'))applyLayout(document.querySelector('#control-editor'),layoutDraft)});
const customArenaBase=startArena;startArena=function(subject){customArenaBase(subject);game.weapon=weaponFor().id;applyBattleControls();document.querySelector('.battle-top')?.insertAdjacentHTML('beforeend','');const zap=document.querySelector('.fire-button strong');if(zap)zap.textContent=weaponFor().name.split(' ')[0].toUpperCase()};
const masteryChallengeBase=initialiseChallenge;initialiseChallenge=function(g){masteryChallengeBase(g);const b=masteryBonuses();g.monsterBonus+=2*b.damage;g.monsterDamage+=Math.floor(b.hp/3)};
const customConnectBase=connectLive;connectLive=function(data,host){customConnectBase(data,host);if(live){live.state.look=lookFor();live.state.weapon=weaponFor().id}};
const customUpdateBar=updateBar;updateBar=function(){customUpdateBar();$('#level').textContent='LVL '+playerLevel()+(playerLevel()===100?' MAX':'');$('#level').title=profile.xp+' XP · Level '+playerLevel()+' / 100'};
const customHeroesBase=heroes;heroes=function(){return customHeroesBase().replace('<section class="pet-overview">','<div class="avatar-tools"><button class="primary" data-custom="studio">✦ Customise fur, hair & outfit</button><button class="secondary" data-custom="weapons">ϟ Armoury</button><button class="secondary" data-custom="controls">✥ Control layout</button></div><section class="pet-overview">')+masteryTrack()};
function masteryTrack(){const level=playerLevel(),b=masteryBonuses();return `<section class="mastery-panel"><span class="eyebrow">YOUR JOURNEY TO LEVEL 100</span><h2>Level ${level} / 100</h2><div class="track"><span style="width:${(level-1)/99*100}%"></span></div><p>${level===100?'Level 100 mastery reached!':Math.max(0,level*150-profile.xp)+' XP to level '+(level+1)+'.'} Mastery bonus: +${b.hp} base hearts · +${b.damage} attack · +${b.superDamage} super.</p><div>${[1,18,35,51,65,80,90,100].map(n=>'<span class="'+(level>=n?'earned':'')+'">LV '+n+'</span>').join('')}</div></section>`}
const customHomeBase=home;home=function(){return customHomeBase().replace('<section class="field-shortcuts">','<div class="avatar-tools"><button class="primary" data-custom="hub">⚙ My setup</button><button class="secondary" data-custom="weapons">ϟ Weapons</button></div><section class="field-shortcuts">')+masteryTrack()};
const customLiveRoster=liveRoster;liveRoster=function(){return live.players.map(p=>`<article class="live-peer">${petPortrait({...getBattleHero(p.hero,p.level),look:p.state.look})}<div><b>${safeText(p.name)} ${p.id===live.hostId?'♛':''}${p.id===live.selfId?' · YOU':''}</b><small>Level ${p.level} · ${p.connected?'Connected':'Reconnecting…'}${live.phase==='quiz'?' · '+(p.state.ready?'Ready · '+p.state.right+'/10':p.state.progress+'/10 answered'):''}</small></div></article>`).join('')};
const customCloseBase=closeRequest;closeRequest=function(){if(document.querySelector('#control-editor')){closeModal();if(game&&!live&&controlsReturnPaused===false)game.paused=false;controlsReturnPaused=null;return}customCloseBase()};
const layoutLiveBegin=beginLiveBattle;beginLiveBattle=function(){layoutLiveBegin();applyBattleControls()};
profile.controls=cleanControls(profile.controls);profile.weapon=weaponFor().id;initBreedArt();updateBar();if(!window.location.hash.startsWith('#room=')&&!window.location.hash.startsWith('#challenge='))navigate('home');
